"""ab-324: Centrail logo mark in every PDF header + a "Generated by
Centrail" / "Page X of Y" footer on every page, for both builders."""

import io
from datetime import date

import pdfplumber
from reportlab.platypus import Table

from app.services.report_pdf import (
    FOOTER_LEFT_TEXT,
    _brand_header,
    _CentrailMark,
    _styles,
    build_report_pdf,
    build_simple_table_pdf,
)


def _page_texts(pdf_bytes: bytes) -> list[str]:
    with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
        return [page.extract_text() or "" for page in pdf.pages]


def _report(categories: int = 2) -> dict:
    return {
        "currency": "KES",
        "total_in": "1000.00",
        "total_out": "500.00",
        "total_saving": "100.00",
        "net": "500.00",
        "reconciled_no_category_total": "0.00",
        "unreconciled_total": "0.00",
        "by_category": [
            {"category_name": f"Category {i}", "category_type": "expense", "total": "10.00"}
            for i in range(categories)
        ],
    }


def _find_mark(flowables) -> _CentrailMark | None:
    for item in flowables:
        if isinstance(item, _CentrailMark):
            return item
        if isinstance(item, Table):
            for row in item._cellvalues:
                for cell in row:
                    cells = cell if isinstance(cell, list | tuple) else [cell]
                    found = _find_mark(cells)
                    if found:
                        return found
    return None


def test_brand_header_contains_the_mark_flowable():
    assert _find_mark(_brand_header(_styles())) is not None


def test_mark_is_sized_from_the_wordmark_cap_height():
    mark = _find_mark(_brand_header(_styles()))
    # Helvetica-Bold cap height is 718/1000 em; the wordmark is 18pt.
    assert abs(mark.size - 18 * 0.718 * 1.3) < 0.5


def test_header_keeps_the_wordmark_text():
    texts = _page_texts(build_simple_table_pdf("Transfers", ["A"], [["x"]]))
    assert "Centrail" in texts[0]
    assert "Transfers Report" in texts[0]


def test_simple_table_pdf_has_footer_on_every_page():
    rows = [[f"Row {i}", str(i)] for i in range(150)]
    texts = _page_texts(build_simple_table_pdf("Transfers", ["Name", "Value"], rows))
    total = len(texts)
    assert total >= 2
    for number, text in enumerate(texts, start=1):
        assert FOOTER_LEFT_TEXT in text
        assert f"Page {number} of {total}" in text
    assert "Page 1 of" in texts[0]
    assert f"Page {total} of {total}" in texts[-1]


def test_report_pdf_has_footer_on_every_page():
    pdf = build_report_pdf(
        _report(categories=120),
        account_name=None,
        from_date=date(2026, 10, 1),
        to_date=date(2026, 10, 31),
        direction=None,
    )
    texts = _page_texts(pdf)
    total = len(texts)
    assert total >= 2
    for number, text in enumerate(texts, start=1):
        assert FOOTER_LEFT_TEXT in text
        assert f"Page {number} of {total}" in text


def test_single_page_pdf_says_page_1_of_1():
    texts = _page_texts(build_simple_table_pdf("Budget Plans", ["A"], [["x"]]))
    assert len(texts) == 1
    assert "Page 1 of 1" in texts[0]
    assert FOOTER_LEFT_TEXT == "Generated by Centrail · centrail.online"


def test_footer_does_not_overlap_table_rows():
    rows = [[f"Row {i}", str(i)] for i in range(150)]
    pdf = build_simple_table_pdf("Transfers", ["Name", "Value"], rows)
    with pdfplumber.open(io.BytesIO(pdf)) as doc:
        for page in doc.pages:
            words = page.extract_words()
            footer_top = min(w["top"] for w in words if w["text"] == "Generated")
            body_bottom = max(
                w["bottom"] for w in words if w["text"].startswith("Row") or w["text"].isdigit() and w["top"] < footer_top - 1
            )
            assert body_bottom < footer_top


def test_mark_is_vertically_centred_on_the_wordmark_capitals():
    pdf = build_simple_table_pdf("Transfers", ["A"], [["x"]])
    with pdfplumber.open(io.BytesIO(pdf)) as doc:
        page = doc.pages[0]
        tile = min(page.rects + page.curves, key=lambda shape: shape["top"])
        cen = next(c for c in page.chars if c["text"] == "C")
        # matrix[5] is the glyph's baseline in PDF (y-up) coordinates.
        baseline_top = page.height - cen["matrix"][5]
        caps_centre = baseline_top - (18 * 0.718) / 2
        tile_centre = (tile["top"] + tile["bottom"]) / 2
        assert abs(tile_centre - caps_centre) < 0.5


def _first_table_line(text: str) -> str:
    """The first line after the page's header block (or the page top on
    continuation pages) that isn't the footer."""
    return next(line for line in text.splitlines() if line.strip() and "Centrail" not in line)


def test_a_long_table_repeats_its_column_headings_on_every_page():
    rows = [[f"Row {i}", str(i)] for i in range(150)]
    texts = _page_texts(build_simple_table_pdf("Transfers", ["Name", "Value"], rows))
    assert len(texts) >= 2
    for text in texts[1:]:
        assert _first_table_line(text).split() == ["Name", "Value"]


def test_a_long_category_breakdown_repeats_its_column_headings_on_every_page():
    pdf = build_report_pdf(
        _report(categories=120),
        account_name=None,
        from_date=date(2026, 10, 1),
        to_date=date(2026, 10, 31),
        direction=None,
    )
    texts = _page_texts(pdf)
    assert len(texts) >= 2
    for text in texts[1:]:
        assert _first_table_line(text).startswith("Category Type Total (KES)")
